from engine import *
topics=[
I('purpose','Първо: тема, цел и посетители',P('Преди да изберем красив фон, трябва да знаем <strong>за какво ще бъде сайтът</strong>. Темата определя предмета: например училищен спортен клуб. Целта показва какво искаме да постигнем: да информираме за тренировките и да привлечем участници.','<strong>Аудитория</strong> наричаме хората, към които е насочен сайтът. Ако са ученици, информацията за мястото и часа на тренировките трябва да е лесна за намиране. За родителите може да са важни и контактите с отговорното лице.','Темата, целта и аудиторията си влияят. Сайт за продажба на спортни обувки има друга задача от сайт за историята на спорта. Не копираме едно оформление, без да преценим нуждите.')+E('Готов план: тема „Нашият спортен клуб“; цел „учениците да намират графика“; аудитория „ученици и родители“. Затова още на началната страница има ясна връзка „Тренировки“.'),[('Тема','Училищен спортен клуб'),('Цел','Лесно намиране на графика'),('Аудитория','Ученици и родители')],C('Кои решения са свързани с доброто начално планиране?',['Определяме темата.','Уточняваме какво трябва да постигне сайтът.','Мислим кои хора ще го използват.','Избираме всичко само по любимия си цвят.','Поставяме важното за аудиторията на достъпно място.','Приемаме, че всеки сайт има една и съща цел.'],[0,1,2,4],'Темата, целта и посетителите насочват съдържанието и оформлението. Любимият цвят сам по себе си не решава потребностите на аудиторията.')),
I('stages','Пътят от идея до поддържан сайт',P('Създаването на сайт не завършва с първата страница. В учебника са описани пет свързани етапа: <strong>проектиране, разработване, публикуване, популяризиране и поддържане</strong>.','При проектирането решаваме какво и за кого ще има. При разработването създаваме страниците и връзките. Публикуването прави готовото съдържание достъпно на уеб адрес. Популяризирането помага хората да научат за сайта. Поддържането пази информацията вярна и работеща.','Тези етапи може да се повтарят. След нова идея или открита грешка се връщаме към плана, променяме и проверяваме. Това не е неуспех, а нормална работа по сайт.')+E('Пример: клубът публикува график. След промяна на часа на тренировките редакторът обновява страницата и проверява връзката към нея. Публикуването на стария график не е последната работа.'),[('План → разработване','Решенията стават страници'),('Публикуване → популяризиране','Достъп и достигане до аудиторията'),('Поддържане','Актуален график и работещи връзки')],C('Кои съчетания са правилни?',['Проектиране — планираме съдържанието.','Разработване — създаваме страниците.','Публикуване — правим сайта достъпен на адрес.','Поддържане — никога не променяме остарялата информация.','Популяризиране — помагаме на хората да научат за сайта.','След първата публикация всички етапи са забранени за повторение.'],[0,1,2,4],'Петте етапа са свързани и могат да се повтарят. Поддръжката включва обновяване и поправки.')),
I('content','Какво съдържание и какви функции са нужни?',P('Съдържанието е онова, което посетителят прочита, вижда или чува. Функцията е онова, което може да направи — например да отвори график, да потърси информация или да изпрати съобщение чрез форма.','За спортния клуб избираме кратко представяне, график, снимки и контакти. Ако целта е само да се намери час за тренировка, не е необходим електронен магазин. Всяка допълнителна функция трябва да има причина.','При планирането описваме и материалите: текст, изображения, анимация, звук или видео. Връзки към социални страници и форми за обратна връзка може да са полезни, ако отговарят на целта и има кой да ги поддържа.')+T(['Нужда','Съдържание или функция'],[['Кога е тренировката?','Актуален график.'],['Къде е залата?','Описание, адрес и карта при нужда.'],['Искам да попитам нещо','Контакт или подходяща форма.']])+E('Добър избор е не най-дългият списък с ефекти, а малък набор, който действително помага на посетителя.'),[('Съдържание','Текст, график, снимки'),('Функции','Меню, търсене, контакт'),('Проверка','Помагат ли на целта и аудиторията?')],C('Кои решения са подходящи за сайта на клуба?',['Актуален график за тренировките.','Контакт за въпроси.','Снимки, които представят дейността.','Задължително добавяне на всеки възможен ефект, дори да пречи.','Функции, съобразени с целта.','Липса на информация за часа, защото фонът е красив.'],[0,1,2,4],'Съдържанието и функциите трябва да решават реални нужди. Ефектите не заменят полезната информация.')),
I('structure','Подреждаме страниците като карта',P('<strong>Структурата</strong> показва какви страници има и как са свързани. Ако ги нарисуваме предварително, по-лесно виждаме дали нещо липсва и дали посетителят ще стигне до него.','В готовия пример Начало води към За клуба, Тренировки, Галерия и Контакти. Всяка вътрешна страница има връзка обратно към Начало. При по-голям сайт може да има и подстраници, например отделни спортове.','<strong>Карта на сайта</strong> може да е страница със списък от връзки към разделите. Тя помага на хората да видят цялото подреждане. Не заменя ясно меню; двете могат да работят заедно.')+E('Проверка на плана: ученик отваря Галерия, после чрез менюто намира Тренировки, без да използва бутона Назад много пъти. Значи основните раздели са достъпни един от друг.'),[('Начало','За клуба / Тренировки / Галерия / Контакти'),('Вътрешни страници','Общо меню и връзка към Начало'),('Карта на сайта','Подреден списък с връзки')],C('Кои решения улесняват структурата?',['Предварителен списък на страниците.','Връзки между основните раздели.','Връзка към Начало от вътрешните страници.','Скрита страница без никаква връзка към нея за най-важния график.','Карта на сайта при подходяща нужда.','Различно случайно меню във всяка страница.'],[0,1,2,4],'Структурата и постоянната навигация помагат на посетителя да се ориентира. Важното съдържание трябва да е достижимо.')),
I('text-design','Четим текст и спокойни цветове',P('Човек обикновено търси отговор, а не иска да разгадава страницата. Затова текстът трябва да е ясен, разделен на кратки абзаци и с точни заглавия. Прекалено дългите редове и дребните букви затрудняват четенето.','В примера използваме един основен шрифт за текста и при нужда втори за заглавията. Препоръката от учебника за малко шрифтове помага на начинаещите, но не е техническа забрана за повече.','Цветовете също имат роля. Светъл фон и тъмен текст дават добър контраст. Един акцент може да подчертава важния бутон. Палитра от няколко съгласувани цвята е по-лесна за поддържане от множество случайни цветове.')+E('Готов избор: бял фон, тъмносин текст и зелен акцент за „График“. Заглавието е по-едро от основния текст. Посетителят вижда кое е важно, без всички думи да са ярки и мигащи.'),[('Текст','Кратки абзаци и ясни заглавия'),('Цветове','Бял фон; тъмносин текст; зелен акцент'),('Шрифтове','Малък последователен набор')],C('Кои избори помагат за четимостта?',['Точни заглавия.','Контрастен текст спрямо фона.','Кратки подредени абзаци.','Много дребен светлосив текст върху бяло.','Последователни шрифтове и цветове.','Мигащ акцент върху всяка дума.'],[0,1,2,4],'Четимостта зависи от подредба, размер, контраст и последователност. Случайните ефекти и слабият контраст затрудняват посетителя.')),
I('images-navigation','Снимки и меню, които помагат',P('Изображението трябва да допълва информацията. Снимка на залата помага да разпознаем мястото за тренировки; случайна снимка без връзка с темата заема място, без да отговаря на въпрос.','Учебникът посочва PNG, GIF и JPG. Избираме подходящ размер и количество, така че страницата да не се зарежда излишно бавно. За важните изображения има кратко текстово описание. Използват се материали, за които имаме нужните права.','<strong>Навигацията</strong> е системата от менюта и връзки. Тя се различава ясно от основния текст. Надпис „График“ е по-разбираем от „Кликни тук“, ако посетителят търси тренировките.')+E('В готовия пример на всички страници има едни и същи четири основни връзки. Посетителят не е принуден да учи ново меню всеки път. Снимките са намалени до необходимия за показване размер.'),[('Полезна снимка','Залата, за която се отнася графикът'),('Ясна връзка','„Тренировки“'),('Постоянно меню','Едни и същи основни раздели')],C('Кои решения са полезни?',['Снимка, която обяснява съдържанието.','Подходящ размер на изображенията.','Ясни надписи на връзките.','Ново случайно меню на всяка страница.','Постоянна навигация между основните раздели.','Все повече огромни снимки независимо от скоростта и целта.'],[0,1,2,4],'Съдържанието, размерите и навигацията служат на потребителя. Излишният обем и непоследователността пречат.')),
I('testing','Проверяваме преди публикуване',P('Красивата начална страница не доказва, че целият сайт работи. Връзката към Контакти може да е грешна, една снимка да липсва, а менюто да излиза извън тесен екран. Затова проверяваме реалните действия.','В готовия пример са отворени всички страници. Натиснати са вътрешните и външните връзки. Изгледът е проверен в различни браузъри и при широк и тесен прозорец. Разгледано е и зареждането при по-бавна връзка.','При намерена грешка се поправя източникът и проверката се повтаря. Ако страницата има формуляр, трябва да се провери и очакваният резултат, а не само видът на полетата.')+T(['Проверка','Наблюдение','Решение'],[['Контакти','Отваря се грешна страница','Поправена връзка.'],['Тесен прозорец','Менюто не се събира','Променено подреждане.'],['Снимки','Зареждат се бавно','Подходящи по-малки файлове.']]),[('Връзки','Водят ли до правилната страница?'),('Изглед','Четимо ли е в различни размери?'),('Зареждане','Няма ли излишно тежки файлове?')],C('Кои проверки са необходими?',['Работят ли връзките.','Показват ли се изображенията.','Четима ли е страницата в тесен прозорец.','Само дали любимият ни цвят е използван.','Как се зарежда съдържанието.','Само началната страница, без останалите.'],[0,1,2,4],'Тестването проверява функционалност, съдържание и показване. Началната страница и цветът не са достатъчни за извод за целия сайт.')),
I('publish','Публикуване: сайтът става достъпен',P('Докато файловете са само в работната папка на автора, съучениците не могат автоматично да ги отворят през интернет. <strong>Публикуване</strong> означава да подготвим достъпна уеб версия на сървър или подходяща услуга.','Сайтът получава адрес. Възможно е да има собствен домейн или адрес, предоставен от платформата. Не е нужно всеки малък учебен сайт да купува отделно име, за да бъде достъпен.','След публикацията се отваря действителният адрес и отново се проверява. Локален път като C:\\Site\\index.html не е същото като публичен адрес. Запазване в редактора и публикуване също не са едно и също.')+E('В готовия пример черновата е проверена, публикувана е и адресът е отворен от друг браузър. Начало, График и Контакти се зареждат; значи публикуваната версия е проверена, а не само местното копие.'),[('Работна папка','Файлове на автора'),('Публикуване','Сървър или услуга за уеб достъп'),('След това','Проверка на действителния адрес')],C('Кои твърдения са верни?',['Локалният файл не е автоматично достъпен през интернет.','Публикуването прави уеб версията достъпна на адрес.','Проверява се и публикуваната версия.','Запазване на чернова винаги е същото като публична публикация.','Адресът може да е предоставен от платформата.','Всеки ученически сайт непременно изисква купен отделен домейн.'],[0,1,2,4],'Местното копие, черновата и уеб версията имат различна достъпност. Платформата може да предоставя адрес; проверката на публикацията остава необходима.')),
I('discover','Как хората откриват полезния сайт?',P('<strong>Популяризиране</strong> означава да помогнем на хората да научат за сайта — например чрез училищна страница или подходяща връзка. Търсачките също могат да откриват и показват страниците.','<strong>Оптимизация за търсене</strong> означава да направим съдържанието ясно, полезно и достъпно за хора и търсачки. Помагат точни заглавия, оригинална информация, описателни връзки и добра структура. Карта на сайта и връзки от подходящи източници могат да улеснят откриването.','Не съществува гарантирано първо място само защото сайтът има много посещения или много връзки. Няма задължителен минимум от десет страници. Заглавието трябва да описва добре съдържанието; примерната дължина 40–50 знака не е универсален технически закон.','Използваме думите, с които аудиторията търси информация, естествено в текста. Не добавяме ненужни страници и случайни връзки само за бройка.')+E('За клуба „График на тренировките по волейбол“ е по-полезно заглавие от „Страница 2“. Най-важният час и място са видими, без посетителят да претърсва целия сайт.'),[('Ясно заглавие','График на тренировките по волейбол'),('Полезно съдържание','Точен час, място и контакт'),('Откриване','Добра структура и подходящи връзки')],C('Кои подходи са полезни?',['Описателни заглавия.','Актуална оригинална информация.','Ясни връзки и структура.','Произволно добавяне на страници само за да станат десет.','Естествени думи, които посетителите използват.','Гаранция за първо място само от много посещения.'],[0,1,2,4],'Полезното съдържание и достъпната структура помагат. Фиксиран брой страници, произволни връзки и обещания за класиране не са надежден подход.')),
I('maintain','Поддръжка: вярно ли е съдържанието и днес?',P('Посетителят не се интересува, че графикът е бил верен преди три месеца. Той иска да знае кога е следващата тренировка. Затова сайтът се нуждае от <strong>поддръжка</strong>: обновяване, поправки и проверка на работата.','В готовия план е определено кой следи за промените. При нов час се обновява графикът; при неработеща връзка се поправя адресът. Изображения, контакти и описания също могат да остареят.','Система за управление на съдържание може да улесни редакцията. И при статичен сайт обаче може да има поддръжка чрез обновяване на файловете. Важно е отговорният човек да разбира структурата и да проверява последствията от промяната.')+E('Променен е часът от 16:00 на 16:30. Поправени са Начало и График, защото и на двете места се показва часът. След това е отворен публикуваният сайт, за да се провери последователността.'),[('Промяна','Тренировка: 16:00 → 16:30'),('Обновени места','Начало и График'),('Проверка','Един и същ актуален час навсякъде')],C('Кои действия са поддръжка?',['Поправяне на остарял график.','Проверка и поправка на връзки.','Обновяване на контактите.','Забрана за промяна след първата публикация.','Проверка на публикувания резултат след обновяване.','Промяна само на едно място, въпреки че часът се вижда различно и на друго.'],[0,1,2,4],'Поддръжката пази съдържанието вярно и последователно. Поправят се всички засегнати места и се проверява публикуваната версия.')),
I('shoe-plan','Готов план за сайт за спортни обувки',P('В заключителната задача от учебника се планира магазин за спортни обувки. Ето завършен пример, в който решенията са свързани с посетителите. Аудиторията са ученици и родители, които търсят удобни обувки за спорт.','Представянето на продукт включва снимки, цена, материал, налични размери и описание за какъв спорт е подходящ. Увеличаване на снимката помага да се видят детайлите. Филтър по размер и категория улеснява избора; списък с избрани продукти или количка има различна роля.','Примерните категории са „Бягане“, „Футбол“ и „Зала“. Планът използва светъл фон, тъмен текст и един зелен акцент. Тези решения се записват преди изграждането, за да няма противоречия между страниците.')+T(['Решение','Причина'],[['Филтър по размер','Посетителят търси обувки, които му стават.'],['Ясна цена и наличност','Позволяват информиран избор.'],['Светъл фон и тъмен текст','Улесняват четенето.']])+E('За личен сайт планът би бил друг, но въпросите остават: тема, цел, аудитория, съдържание, структура, вид и проверка.'),[('Посетител','Търси подходящ размер и спорт'),('Продукт','Снимки, цена, материал, размери'),('Структура','Бягане / Футбол / Зала')],O('Как би обосновал показания план за магазина за спортни обувки?','Напиши един кратък свързан отговор от 4–6 изречения със свои думи и използвай филтъра по размер като пример.','Планът е насочен към ученици и родители, които търсят подходящи спортни обувки. Категориите Бягане, Футбол и Зала помагат да намерят вида, а филтърът по размер — наличните обувки, които им стават. Снимките, цената, материалът и описанието дават информация за избора. Увеличаването показва детайлите. Светлият фон и тъмният текст улесняват четенето. За самопроверка: свържи решенията с нуждите на аудиторията; не изброявай ефекти без обяснение. Възможни са и други добре обосновани решения.'))]
build(17,'static-website-planning','Проектиране на статичен уеб сайт','48–49',P('Полезният сайт започва с план, а не с произволно подреждане на картинки. Ще проследиш как тема, цел и аудитория насочват съдържанието и вида му.','Ще разгледаш всички етапи от проектирането до поддръжката, включително структура, текст, изображения, навигация, проверки и откриване в търсачките. Примерите за спортен клуб и магазин показват защо различните цели водят до различни решения.'),topics,['<strong>Тема, цел и аудитория определят решенията.</strong>','<strong>Планираме съдържание, функции и структура преди разработването.</strong>','<strong>Четим текст, подходящи изображения и ясна навигация помагат на посетителя.</strong>','<strong>Проверяваме местната и публикуваната версия.</strong>','<strong>Популяризирането и поддръжката продължават след публикацията.</strong>'],['Стр.48: тема/цел/аудитория; петте етапа; функционалност/съдържание/структура/дизайн; текст, шрифтове, цветове.','Стр.49: изображенияPNG/GIF/JPG; навигация; браузъри/скорост; публикация/сървър/адрес; популяризиране/търсачки/оптимизация/карта/ключови думи; поддръжка/CMS.','Всички полета на задачата за спортни обувки са обединени в последователен план и една задача за обосновка; план за личен сайт е изведен от същите въпроси.'],[('Google: SEO Starter Guide','https://developers.google.com/search/docs/fundamentals/seo-starter-guide'),('MDN: планиране на сайт','https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started/Your_first_website/What_will_your_website_look_like')], 'Коригирани SEO митове от източника: няма изискване поне10страници, гарантирано класиране по посещаемост или полза от максимален брой случайни връзки;40–50знака за заглавие не е твърд закон. Препоръките за шрифтове/цветове са насоки за начинаещи, не универсална забрана.')
